"""Sample datasets: the synthetic ISP dataset generated by `bsp_seed`
(build/seed, on PYTHONPATH)::

    python -m bsp_seed --target postgres     # → raw.* in bsp_edw
    python -m bsp_seed --target parquet      # → $LAKE_DIR/samples/bsp/*.parquet
"""
from __future__ import annotations

import json
import threading
import time

from . import config
from . import specs as S
from .jobs import Job

STATE_FILE = config.STATE_DIR / "hydrated.json"
TARGETS = ("warehouse", "lake")
TARGET_LABELS = {"warehouse": "Warehouse (Postgres raw schema)", "lake": "Shared lake (Parquet)"}
_lock = threading.Lock()
_cache: dict = {}


def _state() -> dict:
    try:
        return json.loads(STATE_FILE.read_text())
    except (OSError, ValueError):
        return {}


def _mark(ds_id: str, target: str) -> None:
    with _lock:
        st = _state()
        st.setdefault(ds_id, {})[target] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        try:
            STATE_FILE.write_text(json.dumps(st, indent=1))
        except OSError:
            pass


def _parse(out: str):
    for cand in (out, out[out.find("["):] if "[" in out else "", out[out.find("{"):] if "{" in out else ""):
        try:
            return json.loads(cand)
        except ValueError:
            continue
    return None


DATASETS = [{
    "id": "isp",
    "title": "Synthetic ISP dataset (bsp_seed)",
    "description": ("Wire centers (CLLI), customers (BAN), service locations, plans, subscriptions, usage, "
                    "fiber ONT and copper DSL line metrics, network events, service tickets, contact-center calls, "
                    "field dispatches, invoices, the transaction ledger, billing disputes, revenue, NPS surveys and "
                    "the customer_monthly churn table — copper and fiber broadband, 24 months. All personal data "
                    "is synthetic."),
    "tables": ["wire_centers", "customers", "service_locations", "plans", "subscriptions", "usage_monthly",
               "ont_metrics", "copper_line_metrics", "network_events", "service_tickets", "customer_calls",
               "dispatches", "invoices", "transactions", "disputes", "revenue", "nps_surveys", "customer_monthly"],
    "targets": ["warehouse", "lake"],
}]
SEED_TARGET = {"warehouse": "postgres", "lake": "parquet"}


def registry() -> list[dict] | None:
    try:
        import importlib.util  # noqa: PLC0415
        if importlib.util.find_spec("bsp_seed") is None:
            return None
    except (ImportError, ValueError):
        return None
    return DATASETS


def list_datasets() -> dict:
    reg = registry()
    if reg is None:
        return {"script": "python -m bsp_seed", "datasets": [], "targets": TARGET_LABELS,
                "note": "The sample-data generator (bsp_seed) isn't on PYTHONPATH in this container."}
    st = _state()
    out = []
    for d in reg:
        mine = st.get(str(d["id"]), {})
        hyd = d.get("hydrated") if isinstance(d.get("hydrated"), dict) else {}
        targets = [t for t in (d.get("targets") or TARGETS) if t in TARGETS]
        out.append({**d, "title": d.get("title") or d.get("name") or d["id"], "targets": targets,
                    "hydrated": {t: bool(hyd.get(t)) or t in mine for t in targets}, "hydrated_at": mine})
    return {"script": "python -m bsp_seed", "datasets": out, "targets": TARGET_LABELS}


def hydrate_job(ids: list[str], target: str):
    if target not in TARGETS:
        raise S.SpecError(f"target must be one of {', '.join(TARGETS)}")
    ids = [S.dataset_id(i) for i in ids]
    if not ids:
        raise S.SpecError("no datasets selected")
    reg = registry()
    if reg is None:
        raise S.SpecError("the sample-data generator (bsp_seed) isn't available in this container")
    known = {str(d["id"]): d for d in reg}
    if ids != ["all"]:
        for i in ids:
            if i not in known:
                raise S.SpecError(f"unknown dataset {i!r}")
            if target not in (known[i].get("targets") or TARGETS):
                raise S.SpecError(f"dataset {i!r} can't be loaded into the {TARGET_LABELS[target]}")

    def fn(job: Job) -> dict:
        done = []
        for n, i in enumerate(ids, 1):
            job.set_progress(n - 1, len(ids), i)
            job.log(f"\n==> {i} → {TARGET_LABELS[target]}")
            job.run([config.PYTHON, "-m", "bsp_seed", "--target", SEED_TARGET[target]], timeout=3600)
            for k in (known if i == "all" else [i]):
                _mark(k, target)
            done.append(i)
        _cache.clear()
        job.set_progress(len(ids), len(ids), "")
        return {"hydrated": done, "target": target}
    return fn

